def is_even_two_digit_number(num: int) -> bool:
    # exactly two digits (ignoring the sign) and even
    return len(str(abs(num))) == 2 and num % 2 == 0

def count_odd_three_digit_nums(nums: list) -> int:
    count = 0
    for n in nums:
        if n is None:
            continue
        # odd and exactly three digits (ignoring the sign)
        if n % 2 != 0 and len(str(abs(n))) == 3:
            count += 1
    return count

def process_grocery_list(grocery_list: list, task: str):
    if task == "total_bill_amount":
        return sum(item["price"] * item["quantity"] for item in grocery_list)
    if task == "max_quantity_item":
        # max keeps the first item on ties
        return max(grocery_list, key=lambda item: item["quantity"])["name"]
    if task == "sort_by_total_amount":
        # highest total first; ties broken by name ascending
        return sorted(
            grocery_list,
            key=lambda item: (-item["price"] * item["quantity"], item["name"]),
        )
